{
  "highlights": [
    {
      "start_time": 43000,
      "end_time": 55000,
      "description": "男主按下断亲文书的手印后，竟瞬间从村委会穿越到了有椰树海滩的热带海岛，满脸震惊不敢相信。"
    },
    {
      "start_time": 1035000,
      "end_time": 1133000,
      "description": "男主拉着众人看船舱里满筐的大鲍鱼，收鱼老板当场算出总价三千零七十块，所有人都惊呆了。"
    },
    {
      "start_time": 827000,
      "end_time": 853000,
      "description": "男主出海遇致命鼓龙风来不及返航，危急关头大喊海岛空间开启，要连人带船一起进去。"
    },
    {
      "start_time": 0,
      "end_time": 88000,
      "description": "后妈马春花当众逼迫男主牛八一切断亲缘，只分给他一条老船，男主硬气按下手印，宣布从此和牛家各过各的。"
    },
    {
      "start_time": 945000,
      "end_time": 969000,
      "description": "鼓龙风过后，所有人都以为男主死在了海里，结果他开着船平安回到码头，众人震惊，真真当场哭了。"
    },
    {
      "start_time": 1228000,
      "end_time": 1251000,
      "description": "牛家想抢男主赚的钱，男主直接拿出有村委会盖章的断亲文书，当众质问父亲和后妈是不是他们签的字按的手印。"
    },
    {
      "start_time": 1317000,
      "end_time": 1385000,
      "description": "男主信守承诺把卖鲍鱼的八成收入分给何家，还当众向何叔提亲想娶真真，何叔听完直接点头同意亲事。"
    },
    {
      "start_time": 324000,
      "end_time": 355000,
      "description": "男主把海岛空间的海水倒在海边，没过多久就引来大量珍贵的红灯笼鱼，一条就能卖二十多块。"
    },
    {
      "start_time": 426000,
      "end_time": 446000,
      "description": "继兄陈大贵开着机动船过来嘲讽男主的破船要慢慢补，男主丝毫不慌，说自己有靠一桶水引鱼的本事。"
    },
    {
      "start_time": 533000,
      "end_time": 559000,
      "description": "真真偷偷把家里的船钥匙拿给男主，支持他出海打鱼，还叮嘱他就算打不到鱼也要平安回来。"
    },
    {
      "start_time": 120000,
      "end_time": 154000,
      "description": "男主义愤填膺地细数自己十二岁起就在牛家干所有活，挣的钱全交家里，结果断亲只分到一条漏船，当场质问后妈合不合适。"
    },
    {
      "start_time": 132000,
      "end_time": 147000,
      "description": "后妈冲上来想对男主动手，被男主一把攥住手腕动弹不得，男主气场全开，吓得后妈脸色都变了。"
    },
    {
      "start_time": 179000,
      "end_time": 191000,
      "description": "男主当众揭穿继兄买机动船的四千块钱都是自己出海挣的，继兄听完瞬间气急败坏，硬说钱是爸妈给的。"
    },
    {
      "start_time": 294000,
      "end_time": 309000,
      "description": "男主拿着绳子转身离开牛家，临走前放话让牛家最好别后悔今天的选择，以后自己过好了别来认亲戚。"
    },
    {
      "start_time": 369000,
      "end_time": 415000,
      "description": "真真担心男主饿肚子，深夜跑到海边给他送肉包子，结果看到男主煮的是珍贵的红灯笼鱼汤，当场惊呆了。"
    },
    {
      "start_time": 606000,
      "end_time": 629000,
      "description": "真真哥哥发现家里的船钥匙不见了，一家人跑到码头一看，船真的没了，当场急坏了。"
    },
    {
      "start_time": 639000,
      "end_time": 746000,
      "description": "真真当众承认船是自己偷偷借给牛八一的，还拿自己做担保，说男主答应过的事就一定会做到。"
    },
    {
      "start_time": 773000,
      "end_time": 802000,
      "description": "男主跟着蓝色光带到了礁石岛，本来以为只有普通牡蛎，结果发现礁石上长满了大片的大鲍鱼。"
    },
    {
      "start_time": 1055000,
      "end_time": 1087000,
      "description": "村民们看到男主带回来的满筐大鲍鱼，个个都惊呆了，说这哪里是打鱼，分明是捞了一船钱回来。"
    },
    {
      "start_time": 1154000,
      "end_time": 1169000,
      "description": "后妈看到男主赚了三千多块，立刻凑上来想帮他管钱，被男主直接拒绝，明确表示自己和牛家已经没关系了。"
    },
    {
      "start_time": 1260000,
      "end_time": 1267000,
      "description": "男主当众放话，这笔钱是自己冒着鼓龙风的生命危险挣回来的，牛家的人一分钱都别想拿走。"
    },
    {
      "start_time": 1273000,
      "end_time": 1284000,
      "description": "村支书当众表态，既然已经断亲了，就别再拿爹娘那套压人，村民们也纷纷附和，说牛家没钱的时候赶人，有钱了就来要钱，太不地道。"
    },
    {
      "start_time": 1295000,
      "end_time": 1313000,
      "description": "男主对着继兄陈大贵一一打脸他之前的嘲讽，说自己不仅活着回来了，还赚了大钱，警告他别再来管自己的钱，也别为难真真。"
    },
    {
      "start_time": 1439000,
      "end_time": 1459000,
      "description": "男主和真真在海边聊天，说自己一定要盖个带院子的大房子，风风光光把真真娶进门，不让她受一点委屈。"
    },
    {
      "start_time": 1500000,
      "end_time": 1530000,
      "description": "男主把空间海水滴进海里，瞬间引来大量海鲈鱼、石斑鱼，他和真真一起捞了满满一滩，根本抓不过来。"
    },
    {
      "start_time": 1599000,
      "end_time": 1640000,
      "description": "男主想另立门户盖房子娶真真，结果村支书告诉他，分户需要先有房子，盖房又需要先分户，陷入死循环。"
    },
    {
      "start_time": 1658000,
      "end_time": 1698000,
      "description": "村支书答应帮男主去镇上问问批宅基地的事，说最多能批二百平，男主直接就要顶格的，说要有院子有厨房有堂屋，不能让真真受委屈。"
    },
    {
      "start_time": 1736000,
      "end_time": 1749000,
      "description": "何家和男主一起吃定亲饭，桌上摆满了大鱼大肉，一家人有说有笑，氛围十分温馨甜蜜。"
    },
    {
      "start_time": 23000,
      "end_time": 36000,
      "description": "后妈逼男主按断亲手印，男主的手伸到印泥上方却突然停下，后妈当众嘲讽他刚才还硬气，现在就怕了。"
    },
    {
      "start_time": 56000,
      "end_time": 69000,
      "description": "男主喝了一口海岛的椰汁，瞬间就恢复了力气，这才反应过来自己不仅重生了，还把前世的海岛空间也带回来了。"
    }
  ],
  "hook": [
    {
      "start_time": 23000,
      "end_time": 36000,
      "description": "后妈马春花逼迫男主牛八一在断亲文书上按手印，男主的手伸到印泥上方却突然停下，后妈当众嘲讽他刚才还硬气，现在就怂了，继兄也附和说他就是嘴硬，村民们议论纷纷。",
      "hook_type": "冲突悬念",
      "open_question": "男主为什么突然停下不按手印？他最后到底会不会签下这份断亲文书？",
      "end_point_reason": "已成立：后妈当众逼迫男主签断亲文书按手印，男主伸手后突然停在印泥前，遭到后妈、继兄的嘲讽和村民的议论；未展开：男主停下的原因是什么，他最终会不会按下断亲手印。"
    },
    {
      "start_time": 43000,
      "end_time": 55000,
      "description": "男主按下断亲文书的手印后，瞬间从村委会穿越到了有椰树和海滩的陌生热带海岛，他掐了自己确认不是做梦，满脸震惊不知道自己身在何处。",
      "hook_type": "信息悬念",
      "open_question": "男主为什么会突然穿越到海岛上？这个陌生的地方到底是什么来头？",
      "end_point_reason": "已成立：男主按下断亲手印后意外穿越到陌生的热带海岛，确认自己不是在做梦，但完全不知道这是什么地方；未展开：男主穿越的原因是什么，这个海岛究竟有什么秘密。"
    },
    {
      "start_time": 456000,
      "end_time": 484000,
      "description": "男主提出向真真借家里的船出海一晚，承诺鱼获分给真真家八成，自己只留两成，真真十分震惊，问他是不是真的有这个把握，男主坚定地回答说有。",
      "hook_type": "利益期待",
      "open_question": "真真会不会同意把家里的船借给男主？男主真的能靠自己的本事打到鱼兑现承诺吗？",
      "end_point_reason": "已成立：男主向真真提出借船出海一晚的请求，承诺鱼获的八成都分给真真家，自己只留两成，并明确表示自己有把握；未展开：真真会不会答应借船，男主的承诺能否兑现。"
    },
    {
      "start_time": 581000,
      "end_time": 600000,
      "description": "男主把空间海水倒进海里本想引鱼，结果海水不仅没引来鱼，反而化成一道发着蓝光的光带朝着远处游去，男主一脸疑惑，决定开船跟着光带走。",
      "hook_type": "信息悬念",
      "open_question": "蓝色光带为什么会自己游走？它要把男主带到什么地方去？",
      "end_point_reason": "已成立：男主本想用空间海水引鱼，结果海水化成蓝色光带独自向远处游去，男主决定开船跟随光带一探究竟；未展开：蓝色光带为何会自行移动，它要带男主前往何处。"
    },
    {
      "start_time": 827000,
      "end_time": 853000,
      "description": "男主在礁石岛遇到突发的鼓龙风，风浪越来越大，已经来不及返航回码头，危急关头他大喊着启动海岛空间，想要连人带船还有满船鲍鱼一起躲进去。",
      "hook_type": "危机爆发",
      "open_question": "男主能不能成功启动海岛空间躲过鼓龙风？他和船还有满船的鲍鱼能不能平安无事？",
      "end_point_reason": "已成立：男主出海遇致命的鼓龙风，来不及返回码头，危急关头他尝试启动海岛空间，想要连人带船一起躲避风暴；未展开：男主能否成功启动海岛空间，他能不能平安躲过这场风暴。"
    },
    {
      "start_time": 879000,
      "end_time": 907000,
      "description": "鼓龙风过后，出海的渔船都陆续回到了码头，只有男主借的何家的船迟迟不见踪影，陈大贵在一旁嘲讽男主肯定回不来了，真真哭着望向海面喊男主快点回来。",
      "hook_type": "结果悬念",
      "open_question": "男主能不能从鼓龙风里平安回来？他借的船和捕捞的货物还能不能保住？",
      "end_point_reason": "已成立：鼓龙风结束后，其他出海渔船都已安全返回，只有男主驾驶的何家的船迟迟未归，陈大贵趁机嘲讽，真真焦急痛哭；未展开：男主能否平安归来，他借的船和捕捞的货物是否完好。"
    },
    {
      "start_time": 1000000,
      "end_time": 1031000,
      "description": "陈大贵和马春花当众嘲讽男主能活着回来就不错了，还敢说满载而归，纯粹是吹牛，男主没有争辩，只是说今天要让他们笑不出来，拉着真真就往船舱走。",
      "hook_type": "爽点兑现前",
      "open_question": "船舱里到底有没有货？男主能不能拿出证据打脸嘲讽他的牛家人？",
      "end_point_reason": "已成立：陈大贵和马春花当众嘲讽男主吹牛，根本不可能满载而归，男主没有反驳，只说要让他们笑不出来，并拉着真真走向船舱；未展开：船舱里究竟有没有货物，男主能不能打脸众人。"
    }
  ]
}
